def best_block_sum(grid, s):
    R, C = len(grid), len(grid[0])
    pre = [[0] * (C + 1) for _ in range(R + 1)]
    for r in range(R):
        acc = 0
        above, cur, row = pre[r], pre[r + 1], grid[r]
        for c in range(C):
            acc += row[c]
            cur[c + 1] = above[c + 1] + acc
    best = None
    for r in range(s, R + 1):
        for c in range(s, C + 1):
            t = pre[r][c] - pre[r - s][c] - pre[r][c - s] + pre[r - s][c - s]
            if best is None or t > best:
                best = t
    return best

